package io.sandramine;

import android.content.Context;
import android.os.Build;

import org.json.JSONException;
import org.json.JSONObject;

import java.util.Locale;

/** First-run config from config.properties (Config.java is generated by build.sh). */
final class Seed {
    private Seed() {}

    static String json(Context c) {
        JSONObject o = new JSONObject();
        try {
            if (!Config.BTC_ADDRESS.isEmpty()) o.put("btc_address", Config.BTC_ADDRESS);
            o.put("worker_name", Config.WORKER.isEmpty() ? defaultWorker() : Config.WORKER);
            if (!Config.POOL_HOST.isEmpty()) o.put("pool_host", Config.POOL_HOST);
            if (Config.POOL_PORT > 0) o.put("pool_port", Config.POOL_PORT);
            o.put("cpu_threads", Config.THREADS);
            o.put("cpu_usage", Config.CPU);
            o.put("language", Config.LANGUAGE);
            o.put("currency", Config.CURRENCY.isEmpty() ? localCurrency() : Config.CURRENCY);
            o.put("low_priority", true);
        } catch (JSONException e) {
            throw new IllegalStateException(e);
        }
        return o.toString();
    }

    /** The device's currency (BRL on a Brazilian TV), USD if it has none. */
    static String localCurrency() {
        try {
            return java.util.Currency.getInstance(Locale.getDefault()).getCurrencyCode();
        } catch (RuntimeException e) {
            return "USD";
        }
    }

    /** "sm-" + the first word of the model: "BRAVIA 4K GB ATV3" -> "sm-bravia". */
    static String defaultWorker() {
        String model = Build.MODEL == null ? "" : Build.MODEL.trim().split("[\\s_]+")[0];
        String clean = model.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9-]", "");
        if (clean.length() > 24) clean = clean.substring(0, 24);
        return clean.isEmpty() ? "sm-android" : "sm-" + clean;
    }
}
